    .input(UpdateScheduleSchema)
    .mutation(({ ctx, input }) =>
      bus.dispatch(Container.get(UpdateScheduleCommand), {
        ...input,
        organizationId: ctx.activeOrganizationId,
      }),
    ),
  cancelSchedule: writeProcedure
    .input(CampaignIdSchema)
