350	  async updateSchedule(
351	    id: string,
352	    organizationId: string,
353	    data: ScheduleDefinitionInput,
354	  ) {
355	    return this.db.$transaction(async (tx) => {
356	      const schedule = await tx.schedule.findFirst({
357	        where: { id, organizationId },
358	      });
359	      if (!schedule) throw new Error("Schedule not found");
360	      if (["COMPLETED", "CANCELLED"].includes(schedule.status))
361	        throw new Error("Terminal schedules cannot be edited");
362	      const locked = await tx.campaign.count({
363	        where: {
364	          scheduleId: id,
365	          status: { in: ["PENDING_START", "ACTIVE", "PAUSED"] },
366	        },
367	      });
368	      if (locked)
369	        throw new Error(
370	          "Schedule fields are locked while a campaign is pending or active",
371	        );
372	      const sources = await this.validateScheduleSources(
373	        tx,
374	        organizationId,
375	        data,
376	      );
377	      const { sourceCampaignIds, ...scheduleData } = data;
378	      await tx.scheduleSource.deleteMany({ where: { scheduleId: id } });
379	      await tx.campaign.deleteMany({
380	        where: { scheduleId: id, status: "SCHEDULED" },
381	      });
382	      return tx.schedule.update({
383	        where: { id },
384	        data: {
385	          ...scheduleData,
386	          targetGroupId: this.resolveScheduleTarget(data, sources),
387	          nextOccurrenceAt: data.startsAt,
388	          collisionFingerprint: this.service.createScheduleFingerprint(data),
389	          brokenAt: null,
390	          brokenReason: null,
391	          sources: {
392	            create: sourceCampaignIds.map((campaignId, position) => ({
393	              campaignId,
394	              position,
395	            })),
396	          },
397	        },
398	        include: { sources: true },
399	      });
400	    });
401	  }
