486	    createdById: string,
487	  ) {
488	    return this.db.$transaction(async (tx) => {
489	      const schedule = await tx.schedule.findFirst({
490	        where: {
491	          id: scheduleId,
492	          organizationId,
493	          status: { in: ["SCHEDULED", "RUNNING"] },
494	        },
495	        include: { sources: true },
496	      });
497	      if (
498	        !schedule ||
499	        !schedule.sources.some(
500	          (source) => source.campaignId === sourceCampaignId,
501	        )
502	      )
503	        throw new Error("Valid schedule source not found");
504	
505	      const existing = await tx.campaign.findUnique({
506	        where: {
507	          scheduleId_occurrenceAt: { scheduleId, occurrenceAt },
508	        },
509	        include: campaignInclude,
510	      });
511	      if (existing) return existing;
512	
513	      const source = await tx.campaign.findFirst({
514	        where: { id: sourceCampaignId, organizationId },
515	        include: {
516	          emailTemplate: { include: { files: { include: { file: true } } } },
517	          page: true,
518	          mailSendingProfile: true,
519	          targetGroup: { include: { users: true } },
520	        },
521	      });
522	      if (
523	        !source?.emailTemplate ||
524	        source.emailTemplate.visibility !== "CATALOG" ||
525	        source.emailTemplate.status !== "ACTIVE" ||
526	        !source.page ||
527	        source.page.visibility !== "CATALOG" ||
528	        source.page.status !== "ACTIVE" ||
529	        !source.mailSendingProfile ||
530	        source.mailSendingProfile.visibility !== "CATALOG"
531	      )
532	        throw new Error("Schedule source is broken");
533	      const targetGroup =
534	        source.type === "CONCRETE"
535	          ? source.targetGroup?.visibility === "CATALOG" &&
536	            source.targetGroup.status === "ACTIVE"
537	            ? source.targetGroup
538	            : null
539	          : await tx.targetGroup.findFirst({
540	              where: {
541	                id: schedule.targetGroupId ?? "",
542	                organizationId,
543	                visibility: "CATALOG",
544	                status: "ACTIVE",
545	              },
546	              include: { users: true },
547	            });
548	      if (!targetGroup) throw new Error("Target group is unavailable");
549	      const run = await tx.campaign.create({
550	        data: {
551	          organizationId,
552	          createdById,
553	          name: `${source.name} — ${occurrenceAt.toISOString()}`,
554	          tags: source.tags,
555	          type: "CONCRETE",
556	          status: "SCHEDULED",
557	          targetTimezone: schedule.targetTimezone,
558	          autoCompleteAfterDays: schedule.autoCompleteAfterDays,
559	          sourceCampaignId: source.id,
560	          scheduleId: schedule.id,
561	          occurrenceAt,
562	        },
563	      });
564	
565	      const shadowFiles = new Map<string, string>();
566	      for (const link of source.emailTemplate.files) {
567	        const file = link.file;
568	        const shadow = await tx.file.create({
569	          data: {
570	            storedObjectId: file.storedObjectId,
571	            name: file.name,
572	            size: file.size,
573	            format: file.format,
574	            purpose: file.purpose,
575	            visibility: "SHADOW",
576	            organizationId,
577	            uploadedById: file.uploadedById,
578	            shadowCampaignId: run.id,
579	            sourceFileId: file.id,
580	          },
581	        });
582	        shadowFiles.set(file.id, shadow.id);
583	      }
584	      const email = source.emailTemplate;
585	      const shadowEmail = await tx.emailTemplate.create({
586	        data: {
587	          name: email.name,
588	          tags: email.tags,
589	          html: email.html,
590	          design: email.design as Prisma.InputJsonValue,
591	          organizationId,
592	          createdById: email.createdById,
593	          status: email.status,
594	          trackingPixel: email.trackingPixel,
595	          visibility: "SHADOW",
596	          contentRevision: email.contentRevision,
597	          shadowCampaignId: run.id,
598	          sourceTemplateId: email.id,
599	          files: {
600	            create: email.files.map((link) => ({
601	              fileId: shadowFiles.get(link.fileId)!,
602	            })),
603	          },
604	        },
605	      });
606	      const shadowPage = await this.clonePage(
607	        tx,
608	        source.page.id,
609	        organizationId,
610	        run.id,
611	        new Map(),
612	      );
613	      const profile = source.mailSendingProfile;
614	      const shadowProfile = await tx.mailSendingProfile.create({
615	        data: {
616	          organizationId,
617	          name: profile.name,
618	          providerType: profile.providerType,
619	          fromName: profile.fromName,
620	          fromEmail: profile.fromEmail,
621	          replyToEmail: profile.replyToEmail,
622	          headers:
623	            profile.headers === null
624	              ? undefined
625	              : (profile.headers as Prisma.InputJsonValue),
626	          providerConfig: profile.providerConfig as Prisma.InputJsonValue,
627	          isDefault: false,
628	          visibility: "SHADOW",
629	          shadowCampaignId: run.id,
630	          sourceSendingProfileId: profile.id,
631	        },
632	      });
633	      const seen = new Set<string>();
634	      const users = targetGroup.users.flatMap((user) => {
635	        const normalizedEmail = this.service.normalizeRecipientEmail(
636	          user.email,
637	        );
638	        if (seen.has(normalizedEmail)) return [];
639	        seen.add(normalizedEmail);
640	        return [
641	          {
642	            email: user.email.trim(),
643	            normalizedEmail,
644	            firstName: user.firstName,
645	            lastName: user.lastName,
646	            position: user.position,
647	          },
648	        ];
649	      });
650	      const shadowGroup = await tx.targetGroup.create({
651	        data: {
652	          name: targetGroup.name,
653	          status: targetGroup.status,
654	          organizationId,
655	          createdById: targetGroup.createdById,
656	          visibility: "SHADOW",
657	          shadowCampaignId: run.id,
658	          sourceTargetGroupId: targetGroup.id,
659	          users: { create: users },
660	        },
661	      });
662	      return tx.campaign.update({
663	        where: { id: run.id },
664	        data: {
665	          emailTemplateId: shadowEmail.id,
666	          pageId: shadowPage.id,
667	          mailSendingProfileId: shadowProfile.id,
668	          targetGroupId: shadowGroup.id,
669	        },
670	        include: campaignInclude,
671	      });
672	    });
673	  }
